// OFFLINE ONLY. Run licensed/user-supplied BMW jobs against generated bytes.
// Produces protocol test vectors; never reads a car or a vehicle BIN.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const assert=require('node:assert/strict'),{createRequire}=require('node:module');
const argv=process.argv.slice(2);
const arg=name=>{const i=argv.indexOf(name);if(i<0||!argv[i+1])throw Error('Required '+name);return argv[i+1];};
const prgPath=arg('--prg'),moduleRoot=arg('--module-root'),output=arg('--output');
if(fs.existsSync(output))throw Error('Output exists');
const req=createRequire(path.resolve(moduleRoot,'package.json'));
const {parsePrg}=req('@emdzej/ediabasx-best-parser');
const {Interpreter,ParameterSet}=req('@emdzej/ediabasx-interpreter');
const raw=fs.readFileSync(prgPath),prg=parsePrg(raw);
const digest=b=>crypto.createHash('sha256').update(b).digest('hex');
assert.equal(digest(raw),'f38ca2f1db2be9be28da4f2b7fa86a703a99a782e97ba52e0d14a64069be2b73');
const response=p=>Uint8Array.from([0xB8,0xF1,0x12,p.length,...p]);
const cal=Buffer.from(Array.from({length:65536},(_,i)=>(i*37+11)&255));
let captured=[],block=0,seedEvents=[],syntheticSeed;
function buffer(address,length,data){
 const b=Buffer.alloc(21+(data?data.length:0));b.writeUIntLE(address,17,3);b.writeUIntLE(length,13,3);
 if(data)Buffer.from(data).copy(b,21);return b;
}
async function run(job,bin){
 const parameters=new ParameterSet();if(bin)parameters.set(1,{kind:'binary',value:bin});
 const communicationInterface={getInterfaceType:()=> 'STD:OBD',setCommParameter:()=>{},setAnswerLengths:()=>{},
  transmitData:async raw=>{
   const f=Buffer.from(raw),p=f.subarray(4);assert.equal(f[3],p.length);
   let r;
   if(p[0]===0x27){
    if(p[1]===2)r=response([0x67,2,0x34]);
    else if(p[1]===1)r=syntheticSeed;
    else if(p[1]===4)r=response([0x67,4,0x34]);
    else throw Error('Unknown security fixture request');
    seedEvents.push({tx:f.toString('hex'),rx:Buffer.from(r).toString('hex')});return r;
   }
   captured.push({job,payload:p.toString('hex')});
   if(p[0]===0x31&&p[1]===2)return response([0x71,2,0,1]);
   if(p[0]===0x34)return response([0x74,240]);
   if(p[0]===0x36){block++;return response([0x76,block>>8,block&255,1]);}
   if(p[0]===0x37)return response([0x77]);
   if(p[0]===0x31&&p[1]===1)return response([0x71,1,0]);
   throw Error('Unexpected fixture request');
  }};
 const result=await new Interpreter(prg).execute(job,{parameters,communicationInterface});
 assert.equal(result.flat().find(r=>r.name==='JOB_STATUS')?.value,'OKAY');
}
(async()=>{
 await run('FLASH_LOESCHEN',buffer(0x810000,0));
 await run('FLASH_SCHREIBEN_ADRESSE',buffer(0x810000,65536));
 for(let i=0;i<65536;i+=128)await run('FLASH_SCHREIBEN',buffer(0x810000+i,128,cal.subarray(i,i+128)));
 await run('FLASH_SCHREIBEN_ENDE');await run('STATUS_CODIER_CHECKSUMME');
 const NativeDate=Date,seedVectors=[];
 syntheticSeed=response([0x67,1,...Array.from({length:42},(_,i)=>(i*13+7)&255)]);
 for(let second=0;second<39;second++){
  seedEvents=[];global.Date=class extends NativeDate{getSeconds(){return second;}};
  try{
   await run('SEED_KEY');assert.equal(seedEvents.length,3);
   seedVectors.push({nonce:Buffer.from(seedEvents[0].tx,'hex')[9],seedFrame:seedEvents[1].rx,
    key:Buffer.from(seedEvents[2].tx,'hex').subarray(6).toString('hex')});
  }finally{global.Date=NativeDate;}
 }
 const report={synthetic_only:true,vehicle_data:false,physical_test:false,
  prg_sha256:digest(raw),pattern:'byte[i] = (37*i+11) & 255; not firmware',
  calibration_sha256:digest(cal),captured,seedVectors};
 fs.mkdirSync(path.dirname(path.resolve(output)),{recursive:true});
 fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({payloads:captured.length,synthetic_seed_vectors:seedVectors.length,vehicle_data:false}));
})().catch(e=>{console.error(e);process.exitCode=1;});
